BEGIN;
ALTER TABLE campaigns ADD COLUMN ai_agent_id uuid REFERENCES ai_agents(id);
CREATE TABLE ai_voice_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),call_job_id uuid NOT NULL REFERENCES campaign_call_jobs(id),ai_agent_id uuid REFERENCES ai_agents(id),provider_stream_id text NOT NULL UNIQUE,state text NOT NULL DEFAULT 'connected' CHECK(state IN('connected','active','interrupted','handoff','completed','failed')),input_frames bigint NOT NULL DEFAULT 0,output_frames bigint NOT NULL DEFAULT 0,input_bytes bigint NOT NULL DEFAULT 0,output_bytes bigint NOT NULL DEFAULT 0,current_speaker text CHECK(current_speaker IN('caller','ai','human')),started_at timestamptz NOT NULL DEFAULT now(),ended_at timestamptz,last_error text);
CREATE TABLE ai_voice_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),voice_session_id uuid NOT NULL REFERENCES ai_voice_sessions(id),event_type text NOT NULL,payload jsonb NOT NULL DEFAULT '{}'::jsonb,occurred_at timestamptz NOT NULL DEFAULT now());CREATE INDEX ai_voice_events_session_idx ON ai_voice_events(voice_session_id,occurred_at);
ALTER TABLE ai_voice_sessions ENABLE ROW LEVEL SECURITY;ALTER TABLE ai_voice_sessions FORCE ROW LEVEL SECURITY;ALTER TABLE ai_voice_events ENABLE ROW LEVEL SECURITY;ALTER TABLE ai_voice_events FORCE ROW LEVEL SECURITY;CREATE POLICY ai_voice_sessions_isolation ON ai_voice_sessions USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY ai_voice_events_isolation ON ai_voice_events USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);
COMMIT;
